#!/usr/bin/env bash
#
# gen-downloads-manifest.sh — emit site/downloads.json (spec §D) for a release.
#
# The website (site/download.html + site/site.js) consumes this manifest to
# render real per-platform download links; it is regenerated by the release
# workflow's `finalize` job after every asset has been uploaded.
#
# Usage:
#   gen-downloads-manifest.sh <tag> <owner/repo> <SHA256SUMS> <asset-name>...
#
#   tag          release tag, e.g. v0.1.0 (the version is the tag without "v")
#   owner/repo   the public repo hosting the Release, e.g. mrbrutti/aitmproxy
#   SHA256SUMS   path to the combined checksums file (one "<hash>  <name>" per line)
#   asset-name   one or more uploaded asset file names (not paths)
#
# Emits the manifest JSON to stdout. Pure bash + coreutils; no jq required.
# The release date defaults to today (UTC) and can be pinned with RELEASED.
set -euo pipefail

if [ "$#" -lt 4 ]; then
  echo "usage: $0 <tag> <owner/repo> <SHA256SUMS> <asset-name>..." >&2
  exit 2
fi

tag=$1
repo=$2
sums=$3
shift 3

if [ ! -f "$sums" ]; then
  echo "error: SHA256SUMS file not found: $sums" >&2
  exit 1
fi

version=${tag#v}
released=${RELEASED:-$(date -u +%Y-%m-%d)}
release_url="https://github.com/${repo}/releases/tag/${tag}"

# JSON string escaper (backslash, double-quote, control chars we may plausibly meet).
json_str() {
  local s=$1
  s=${s//\\/\\\\}
  s=${s//\"/\\\"}
  printf '"%s"' "$s"
}

# Look up a file's sha256 in the SHA256SUMS file. Lines are "<hash>  <name>"
# (shasum -a 256 format; the name may be prefixed with "*" for binary mode).
sha_for() {
  local want=$1 hash name
  while read -r hash name; do
    [ -n "$hash" ] || continue
    name=${name#\*}
    name=${name##*/}
    if [ "$name" = "$want" ]; then
      printf '%s' "$hash"
      return 0
    fi
  done < "$sums"
  return 1
}

# Infer the download format from an asset file name.
format_for() {
  case $1 in
    *.tar.gz) printf 'tar.gz' ;;
    *.deb)    printf 'deb' ;;
    *.rpm)    printf 'rpm' ;;
    *.dmg)    printf 'dmg' ;;
    *)        return 1 ;;
  esac
}

# Infer the platform from an asset file name. .deb/.rpm are Linux-only package
# formats whose names carry no OS token, so they map to linux by format.
platform_for() {
  case $1 in
    *.dmg)                printf 'macos' ;;
    *apple-darwin*)       printf 'macos' ;;
    *linux*|*.deb|*.rpm)  printf 'linux' ;;
    *)                    return 1 ;;
  esac
}

# Infer a normalised arch (x86_64 | aarch64) from an asset file name.
# .dmg carries no arch token; macOS ships arm64 only (spec §A), so default aarch64.
arch_for() {
  case $1 in
    *x86_64*|*amd64*)     printf 'x86_64' ;;
    *aarch64*|*arm64*)    printf 'aarch64' ;;
    *.dmg)                printf 'aarch64' ;;
    *)                    return 1 ;;
  esac
}

printf '{\n'
printf '  "version": %s,\n' "$(json_str "$version")"
printf '  "tag": %s,\n' "$(json_str "$tag")"
printf '  "released": %s,\n' "$(json_str "$released")"
printf '  "release_url": %s,\n' "$(json_str "$release_url")"
printf '  "assets": [\n'

count=0
for name in "$@"; do
  format=$(format_for "$name") || { echo "error: unknown format for asset: $name" >&2; exit 1; }
  platform=$(platform_for "$name") || { echo "error: unknown platform for asset: $name" >&2; exit 1; }
  arch=$(arch_for "$name") || { echo "error: unknown arch for asset: $name" >&2; exit 1; }
  sha=$(sha_for "$name") || { echo "error: no SHA256SUMS entry for asset: $name" >&2; exit 1; }
  url="https://github.com/${repo}/releases/download/${tag}/${name}"

  if [ "$count" -gt 0 ]; then
    printf ',\n'
  fi
  printf '    {\n'
  printf '      "platform": %s,\n' "$(json_str "$platform")"
  printf '      "arch": %s,\n' "$(json_str "$arch")"
  printf '      "format": %s,\n' "$(json_str "$format")"
  printf '      "name": %s,\n' "$(json_str "$name")"
  printf '      "url": %s,\n' "$(json_str "$url")"
  printf '      "sha256": %s\n' "$(json_str "$sha")"
  printf '    }'
  count=$((count + 1))
done

printf '\n  ]\n'
printf '}\n'
